/// V1 fix: `(**(code **)(pLocalDataFireBallBig + 4))()`: the state-machine slot holds one of these
/// functions' addresses
fn call_state(e: &mut Engine, a: u32) -> LResult<()> {
    match a {
        0x10e78 => fireBallBigST_Waiting_In(e),
        0x10ed8 => fireBallBigST_Waiting_Execute(e),
        0x10f70 => fireBallBigST_Creation_In(e),
        0x11058 => fireBallBigST_Creation_Execute(e),
        0x110f0 => fireBallBigST_Thrown_In(e),
        0x114a0 => fireBallBigST_Thrown_Execute(e),
        _ => panic!("fireballbig: call through a non-state pointer {a:#x}"),
    }
}
